{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Levomepromazine, a tricyclic neuroleptic with a methoxy substituent and dimethylaminoalkyl side chain, has an absolute oral bioavailability of 30-70% in humans, supporting that the query's similar tricyclic basic-amine scaffold can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Imipramine, a tricyclic antidepressant with a dimethylaminopropyl side chain, showed absolute oral bioavailability of 47.3% (range 29-77%) in normal subjects, supporting a high F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Chlorimipramine, a close tricyclic analogue with a dimethylaminopropyl side chain, had absolute oral bioavailability ranging from 36% to 68% (mean 48%) in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Promethazine, a tricyclic phenothiazine with a dimethylaminoisopropyl side chain, had an absolute oral bioavailability of 25% in healthy volunteers, which is above the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Encainide, a structurally different drug with methoxy and basic-amine features, showed an absolute oral bioavailability of 20-30% in healthy subjects, providing additional support that the query is likely to exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prothipendyl, a tricyclic azaphenothiazine with a dimethylaminopropyl side chain, was reported to have low absolute bioavailability in healthy volunteers; this is a contradictory example, but its structural differences and lower transferability limit its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple tricyclic analogues with basic dimethylaminoalkyl side chains and methoxy/aromatic features show absolute oral bioavailability values of 25-74%, all above the 20% threshold. The only low-bioavailability analogue, prothipendyl, is structurally less transferable. A modified-release formulation would not be expected to reduce the extent of absorption below 20%, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct diltiazem absolute bioavailability record is present in the retrieved evidence set; all evidence comes from analogues with low-to-moderate Morgan similarity.",
    "No formulation-specific absolute bioavailability data for the query under modified-release conditions are available.",
    "The contradictory prothipendyl result indicates possible first-pass liability, but its azaphenothiazine structure and lack of the query's methoxyphenyl/ester features reduce direct transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

